// Small CDP measurement probe (not part of the repo).
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

const PORT = 9333;
const URL_ = process.argv[2] || 'http://127.0.0.1:8787/';
const userDataDir = path.join(os.tmpdir(), `measure-${process.pid}`);
const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
  '--hide-scrollbars', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`,
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let target;
for (let i = 0; i < 100 && !target; i++) {
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
    if (res.ok) target = (await res.json()).webSocketDebuggerUrl;
  } catch {}
  if (!target) await sleep(200);
}
if (!target) { chrome.kill('SIGKILL'); throw new Error('no devtools'); }
const ws = new WebSocket(target);
await new Promise((r, j) => { ws.addEventListener('open', r, { once: true }); ws.addEventListener('error', j, { once: true }); });
let id = 0;
const pending = new Map();
ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const n = ++id;
  pending.set(n, (m) => (m.error ? reject(new Error(`${method}: ${m.error.message}`)) : resolve(m.result)));
  ws.send(JSON.stringify({ id: n, method, params }));
});
const evaluate = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 300));
  return r.result.value;
};

await send('Page.enable');
await send('Runtime.enable');

const viewports = [[390, 844], [320, 640], [1440, 900]];
const results = [];
for (const [w, h] of viewports) {
  await send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 1, mobile: w < 600 });
  await send('Page.navigate', { url: URL_ });
  await sleep(2500);
  const m = await evaluate(`(() => {
    const box = (sel) => { const n = document.querySelector(sel); if (!n) return null; const r = n.getBoundingClientRect(); return { top: Math.round(r.top + scrollY), height: Math.round(r.height) }; };
    return {
      scrollHeight: document.documentElement.scrollHeight,
      header: box('.zh-header'),
      intro: box('.app-intro'),
      toolbar: box('.app-toolbar'),
      map: box('#map'),
      grid: box('.app-grid'),
      facts: box('#intro-facts'),
      tags: box('#intro-tags'),
      more: box('.app-intro__more'),
      h1: box('#intro-heading'),
      lead: box('.zh-lead'),
      toolbarGroups: [...document.querySelectorAll('.app-toolbar__group')].map((g) => Math.round(g.getBoundingClientRect().height)),
      compare: box('#compare-open'),
    };
  })()`);
  results.push({ viewport: `${w}x${h}`, ...m });
}
console.log(JSON.stringify(results, null, 1));
ws.close();
chrome.kill('SIGKILL');
process.exit(0);

