/*!
 * App layout – Kartenzeit (historical map explorer).
 * Composition only; visual language comes from the canton tokens/components.
 */

.app-main {
  padding-block: var(--zh-size-large) 0;
}

.app-intro {
  background: var(--zh-white);
  border: 1px solid var(--zh-color-border);
  padding: var(--zh-size-large) var(--zh-size-regular);
  margin-bottom: var(--zh-size-large);
}

.app-intro p {
  margin-bottom: var(--zh-size-small-regular);
}

/* The “read more” link only matters where the lead paragraph is clamped. */
.app-intro__more {
  display: none;
}

.app-intro__more-short {
  display: none;
}

/* Map-first composition: from 840 px (the cantonal `medium` breakpoint, where
   the shell gets its 16 px gutters and the two-column header) the orientation
   block becomes a compact band instead of a full-height page. The headline keeps its cantonal 3 px rule
   across the full width; the stock figures move to the right of the lead
   paragraph and carry the characteristic 3 px left rule instead of a bottom
   rule. Only the clamped lead text is truncated — the complete wording stands
   in “Über das Projekt” (#about), which the “mehr” link targets. */
@media (min-width: 840px) {
  .app-intro {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(240px, 4fr);
    grid-template-areas:
      'head head'
      'lead facts'
      'more tags';
    gap: var(--zh-size-small-regular) var(--zh-column-gap);
    align-items: start;
    padding: var(--zh-size-regular);
    margin-bottom: var(--zh-size-regular);
  }
  .app-intro > .zh-heading--1 {
    grid-area: head;
    margin-bottom: 0;
  }
  .app-intro > .zh-lead {
    grid-area: lead;
    margin: 0;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .app-intro__more {
    grid-area: more;
    display: block;
    margin: 0;
  }
  .app-intro > .zh-facts {
    grid-area: facts;
    margin: 0;
    padding: 0 0 0 var(--zh-indent);
    border-bottom: 0;
    border-left: var(--zh-rule) solid var(--zh-black);
    gap: var(--zh-size-small-regular) var(--zh-size-regular);
  }
  .app-intro > .zh-tags {
    grid-area: tags;
    margin: 0;
    justify-content: flex-start;
  }
}

/* Facts strip: cantonal “chapter number” rhythm — value first, label under it. */
.zh-facts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--zh-size-large);
  margin: 0 0 var(--zh-size-regular);
  padding: 0 0 var(--zh-size-small-regular);
  list-style: none;
  border-bottom: 1px solid var(--zh-color-border);
}

.zh-facts li {
  display: flex;
  flex-direction: column-reverse;
  gap: 2px;
}

.zh-facts__value {
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-medium);
  font-weight: 900;
  letter-spacing: -0.01em;
}

.zh-facts__term {
  font-size: var(--zh-font-tiny);
  color: var(--zh-color-text-soft);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.zh-check-field {
  margin-bottom: var(--zh-size-large);
}

.app-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--zh-size-small-regular);
  padding: var(--zh-size-small-regular) var(--zh-size-regular);
  background: var(--zh-black-5);
  border-top: var(--zh-rule) solid var(--zh-black);
  margin-bottom: var(--zh-size-regular);
}

.app-toolbar__group {
  display: flex;
  align-items: center;
  gap: var(--zh-size-tiny);
}

.app-toolbar__label {
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-bigger-regular);
  font-weight: 900;
}

.app-toolbar .zh-label {
  margin: 0;
}

.app-toolbar .zh-select,
.app-filters .zh-select {
  min-height: var(--zh-size-big);
  font-size: var(--zh-font-small);
}

.app-toolbar .zh-select {
  width: auto;
}

/* ---- View switch: list only / map only / split ---- */
.app-grid {
  display: grid;
  gap: var(--zh-column-gap);
  align-items: start;
}

/* Single-column layouts (phones and tablets) put the map first: a map explorer
   whose map sits below a 40-entry result list is unusable on a phone. The DOM
   order stays list-first for screen readers and the tab order, and the map
   keeps its own keyboard controls. */
@media (max-width: 1023px) {
  .app-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .app-mapwrap {
    order: -1;
  }
}

.app-view--map .app-grid {
  grid-template-columns: minmax(0, 1fr);
}

.app-view--map .app-side {
  display: none;
}

.app-view--map .app-map,
.app-view--map .app-mapwrap {
  /* The map container must stay positioned: its tiles, extents and markers are
     absolutely positioned children (see .map-layer in map.js). A `position:
     static` override made them escape the box — they painted over the intro
     and produced ~80 px of horizontal page overflow. */
  position: relative;
  top: auto;
  height: min(78vh, 760px);
}

/* In map-only view the map is the page: the intro and its facts would push it
   below the fold again. The toolbar keeps the way back to the other views. */
.app-view--map .app-intro {
  display: none;
}

.app-view--list .app-grid {

/* ---- Small screens: keep the way to the map short ---- */
.zh-header__note-short {
