// Independent audit probe (not part of the repo).
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

const PORT = 9345;
const URL_ = process.argv[2] || 'http://127.0.0.1:8787/';
const userDataDir = path.join(os.tmpdir(), `audit-${process.pid}`);
const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
  '--hide-scrollbars', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`,
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let target;
for (let i = 0; i < 100 && !target; i++) {
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
    if (res.ok) target = (await res.json()).webSocketDebuggerUrl;
  } catch {}
  if (!target) await sleep(200);
}
if (!target) { chrome.kill('SIGKILL'); throw new Error('no devtools'); }
const ws = new WebSocket(target);
await new Promise((r, j) => { ws.addEventListener('open', r, { once: true }); ws.addEventListener('error', j, { once: true }); });
let id = 0;
const pending = new Map();
ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const n = ++id;
  pending.set(n, (m) => (m.error ? reject(new Error(`${method}: ${m.error.message}`)) : resolve(m.result)));
  ws.send(JSON.stringify({ id: n, method, params }));
});
const evaluate = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 400));
  return r.result.value;
};
await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: URL_ });
await sleep: 0;
await sleep(3000);

const audit = await evaluate(`(() => {
  const visible = (n) => { const r = n.getBoundingClientRect(); const s = getComputedStyle(n); return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none'; };
  const name = (n) => (n.getAttribute('aria-label') || n.getAttribute('title') || n.textContent || '').trim().replace(/\\s+/g, ' ').slice(0, 70)
    || (n.placeholder ? '(' + n.placeholder + ')' : '');
  const interactive = [...document.querySelectorAll('a[href], button, input, select, textarea, [tabindex]')].filter(visible);
  const noName = interactive.filter((n) => !name(n));
  const brokenImages = [...document.images].filter((i) => i.currentSrc || i.src).filter((i) => i.complete && i.naturalWidth === 0).map((i) => i.src.slice(0, 120));
  const notLoaded = [...document.images].filter((i) => !i.complete).map((i) => i.src.slice(0, 120));
  const hiddenButVisible = [...document.querySelectorAll('[hidden]')].filter(visible).map((n) => n.id || n.className);
  const focusableHidden = interactive.filter((n) => n.tabIndex >= 0 && (n.getBoundingClientRect().width === 0 || getComputedStyle(n).visibility === 'hidden'));
  return {
    title: document.title,
    interactiveCount: interactive.length,
    noName: noName.map((n) => n.tagName + '#' + n.id + '.' + String(n.className).slice(0, 30) + '|' + (n.type || '')),
    brokenImages, notLoaded, hiddenButVisible,
    focusableHidden: focusableHidden.map((n) => n.tagName + '#' + n.id),
    buttons: [...document.querySelectorAll('button')].map((b) => ({ id: b.id || null, text: name(b), visible: visible(b), disabled: b.disabled })),
    links: [...document.querySelectorAll('a[href]')].map((a) => ({ href: a.getAttribute('href'), text: name(a), external: a.target === '_blank' || /^https?:/.test(a.getAttribute('href')), rel: a.getAttribute('rel') })),
    moduleErrors: document.documentElement.dataset.moduleErrors || null,
    selectWidths: [...document.querySelectorAll('select,input,button')].filter(visible).map((n) => ({ id: n.id, w: Math.round(n.getBoundingClientRect().width), h: Math.round(n.getBoundingClientRect().height) })),
  };
})()`);
console.log(JSON.stringify(audit, null, 1));

// Focus ring check: tab through the first 25 stops, record the focused element and computed outline.
const ring = await evaluate(`(async () => {
  const out = [];
  document.body.focus();
  const seen = [];
  for (let i = 0; i < 25; i++) {
    const before = document.activeElement;
    const ev = new KeyboardEvent('keydown', { key: 'Tab', bubbles: true });
    document.dispatchEvent(ev);
    // CDP needs a real Tab; fall back to the browser's own focus navigation below.
    seen.push(before && (before.id || before.tagName));
  }
  return seen;
})()`);
console.log('focus-before-tab-sequence:', JSON.stringify(ring));

for (let i = 0; i < 22; i++) {
  await send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key: 'Tab', code: 'Tab', windowsVirtualKeyCode: 9 });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Tab', code: 'Tab', windowsVirtualKeyCode: 9 });
  const info = await evaluate(`(() => {
    const n = document.activeElement;
    if (!n) return null;
    const s = getComputedStyle(n);
    return { tag: n.tagName, id: n.id || null, name: (n.getAttribute('aria-label') || n.textContent || '').trim().replace(/\\s+/g, ' ').slice(0, 50),
      outline: s.outlineStyle + ' ' + s.outlineWidth + ' ' + s.outlineColor + ' offset ' + s.outlineOffset, visible: n.getBoundingClientRect().width > 0 };
  })()`);
  console.log('TAB', i + 1, JSON.stringify(info));
}
ws.close();
chrome.kill('SIGKILL');
process.exit(0);

