// One-off experiment: measure mobile layout before/after candidate CSS.
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

const PORT = 9351;
const URL_ = 'http://127.0.0.1:8787/';
const userDataDir = path.join(os.tmpdir(), `exp-${process.pid}`);
const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
  '--hide-scrollbars', `--remote-debugging-port=${PORT}`, `--user-data-dir=${userDataDir}`, 'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let target;
for (let i = 0; i < 100 && !target; i++) {
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
    if (res.ok) target = (await res.json()).webSocketDebuggerUrl;
  } catch {}
  if (!target) await sleep(200);
}
const ws = new WebSocket(target);
await new Promise((r, j) => { ws.addEventListener('open', r, { once: true }); ws.addEventListener('error', j, { once: true }); });
let id = 0; const pending = new Map();
ws.addEventListener('message', (ev) => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params = {}) => new Promise((res, rej) => { const n = ++id; pending.set(n, (m) => (m.error ? rej(new Error(m.error.message)) : res(m.result))); ws.send(JSON.stringify({ id: n, method, params })); });
const evaluate = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.value;
await send('Page.enable'); await send('Runtime.enable');

const MEASURE = `(() => {
  const t = (sel) => { const n = document.querySelector(sel); if (!n) return null; const r = n.getBoundingClientRect(); return Math.round(r.top + scrollY); };
  return { header: t('.zh-header'), intro: t('.app-intro'), toolbar: t('.app-toolbar'), map: t('#map'),
    scrollHeight: document.documentElement.scrollHeight,
    overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth };
})()`;

const CANDIDATE = `
@media (max-width: 599px) {
  .app-intro > .zh-facts { display: none; }
  .app-intro { padding: 8px 12px; margin-bottom: 8px; }
  .app-intro .zh-heading--1 { margin-bottom: 4px; }
  .app-intro .zh-lead { margin-bottom: 4px; }
  .app-intro__more { margin-bottom: 0; }
  .app-toolbar { padding: 4px 8px; gap: 4px; margin-bottom: 8px; }
  .zh-header__main { padding-block: 8px; }
  .zh-header__bar-inner { padding-block: 4px; }
  .app-main { padding-block: 8px 0; }
}
@media (max-width: 399px) {
  .zh-brand__claim { display: none; }
  .zh-header__note-short { font-size: 12px; }
}
`;

for (const [w, h] of [[390, 844], [320, 640]]) {
  await send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 1, mobile: true });
  await send('Page.navigate', { url: URL_ });
  await sleep(2500);
  const before = await evaluate(MEASURE);
  await evaluate(`(() => { const s = document.createElement('style'); s.id='exp'; s.textContent = ${JSON.stringify(CANDIDATE)}; document.head.append(s); return true; })()`);
  await sleep(300);
  const after = await evaluate(MEASURE);
  console.log(`${w}x${h}`, JSON.stringify({ before, after }, null, 0));
}
ws.close(); chrome.kill('SIGKILL'); process.exit(0);

