const chrome = spawn('chromium', ['--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--hide-scrollbars',`--remote-debugging-port=${PORT}`,`--user-data-dir=${udd}`,'about:blank'],{stdio:['ignore','pipe','pipe']});
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
let target; for(let i=0;i<100&&!target;i++){try{const res=await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`,{method:'PUT'});if(res.ok)target=(await res.json()).webSocketDebuggerUrl;}catch{} if(!target)await sleep(200);}
const ws=new WebSocket(target); await new Promise((r,j)=>{ws.addEventListener('open',r,{once:true});ws.addEventListener('error',j,{once:true});});
let id=0;const pending=new Map();ws.addEventListener('message',(ev)=>{const m=JSON.parse(ev.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}});
const send=(method,params={})=>new Promise((res,rej)=>{const n=++id;pending.set(n,(m)=>(m.error?rej(new Error(m.error.message)):res(m.result)));ws.send(JSON.stringify({id:n,method,params}));});
const evaluate=async(e)=>(await send('Runtime.evaluate',{expression:e,returnByValue:true})).result.value;
await send('Page.enable'); await send('Runtime.enable');
const outdir='/tmp/shots-716-mobile'; fs.mkdirSync(outdir,{recursive:true});
await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:2,mobile:true});
await send('Page.navigate',{url:URL_}); await sleep(3000);
let shot=await send('Page.captureScreenshot',{format:'png'}); fs.writeFileSync(path.join(outdir,'a-top.png'),Buffer.from(shot.data,'base64'));
await evaluate(`document.querySelector('#about').scrollIntoView({behavior:'instant',block:'start'}); true`); await sleep(600);
shot=await send('Page.captureScreenshot',{format:'png'}); fs.writeFileSync(path.join(outdir,'b-about.png'),Buffer.from(shot.data,'base64'));
await send('Emulation.setDeviceMetricsOverride',{width:320,height:640,deviceScaleFactor:2,mobile:true});
